      {"unit_id": "u-1f26bb9c4ca01b89207f", "start_line": 84, "end_line": 97, "role": "primary", "dependency_reason": ""}
    ]
  },
  "feasible_trigger": {
    "status": "established",
    "reason": "The four byte witness passes the entry gates. In a CHARBOUND|STRIPCC map setup, CHARBOUND creates sentinels for the retained letters and the after normalization branch keeps them while removing the intervening control and its sentinel.",
