      {"unit_id": "u-1f26bb9c4ca01b89207f", "start_line": 84, "end_line": 97, "role": "dependency", "dependency_reason": "The entry passes accepted text to its fixed map calls."}
    ]
  },
  "observable_consequence": {
    "status": "established",
    "reason": "The supported combined mapping emits markers for retained graphemes after stripping the control. No fixed map call reaches that behavior, so it is blocked target coverage.",
