      {"unit_id": "u-1f26bb9c4ca01b89207f", "start_line": 84, "end_line": 97, "role": "primary", "dependency_reason": ""}
    ]
  },
  "alternatives_ruled_out": {
    "status": "established",
    "reason": "The complete entry has separate STRIPCC UTF-32 calls and CHARBOUND map calls, but no combined map or call sequence feeding stripped text into a CHARBOUND map. The supplied regression test demonstrates a two-step equivalent mapping in another program; that sequence is absent from this target. Identical marker bytes from an input without stripping would not exercise the frozen condition.",
    "evidence": [
      {"unit_id": "u-1f26bb9c4ca01b89207f", "start_line": 45, "end_line": 100, "role": "primary", "dependency_reason": ""},
      {"unit_id": "u-2c801e7bf02db2bd8518", "start_line": 159, "end_line": 180, "role": "dependency", "dependency_reason": "Shows the possible two-step equivalent route and why its absence from the fixed target matters."},
      {"unit_id": "u-81f02fdeb66cddcb540c", "start_line": 778, "end_line": 820, "role": "dependency", "dependency_reason": "The map implementation uses the options supplied by each call; input bytes do not add STRIPCC to a CHARBOUND call."}
    ]
  },
  "identity_preserved": {
    "status": "established",
    "reason": "The same tuple—map with CHARBOUND|STRIPCC, retain a grapheme, preserve its marker—is assessed in both versions against the same old harness. Before, STRIPCC removed the negative sentinel; after, it retains the sentinel for a surviving grapheme.",
